/**
 * Vertical layout primitive (`design/components/stack.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/stack.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'
import { Dynamic } from 'solid-js/web'

import {
  claimSlot,
  classes,
  mergeParts,
  scope,
  spacingAttrs,
  type Defaults,
  type LayoutPatch,
  type SpaceStep,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/layout/layout.module.css'

export type StackAlign = NonNullable<StackProps['align']>

export type StackElement = NonNullable<StackProps['as']>

export type StackJustify = NonNullable<StackProps['justify']>

export interface StackProps {
  align?: 'stretch' | 'start' | 'center' | 'end'
  /**
   * List and form semantics without a wrapper element.
   */
  as?: 'form' | 'div' | 'section' | 'ul' | 'ol'
  children?: JSX.Element
  gap?: SpaceStep
  justify?: 'start' | 'center' | 'end' | 'between'
  p?: SpaceStep
  patch?: LayoutPatch
  px?: SpaceStep
  py?: SpaceStep
}

/** Vertical layout primitive. */
export default function Stack(given: StackProps): JSX.Element {
  const props = mergeProps(
    { align: 'stretch', justify: 'start', as: 'div' } as Defaults<
      StackProps,
      'align' | 'justify' | 'as'
    >,
    claimSlot(given),
  )
  return scope(() => {
    return (
      <Dynamic
        component={props.as}
        {...mergeParts(
          spacingAttrs({
            gap: props.gap,
            p: props.p,
            px: props.px,
            py: props.py,
            patch: props.patch,
          }),
          {
            class: classes(styles.layout, styles.stack),
            'data-align': props.align,
            'data-justify': props.justify,
            'data-member': 'stack',
          },
        )}
      >
        {props.children}
      </Dynamic>
    )
  })
}
